-- Canonical schema is also declared in app/models.py; startup applies it idempotently.
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incidents (id SERIAL PRIMARY KEY, title VARCHAR(240) NOT NULL, description TEXT NOT NULL, severity VARCHAR(20) NOT NULL, service_name VARCHAR(120) NOT NULL, logs TEXT NOT NULL DEFAULT '', tags JSONB NOT NULL DEFAULT '[]', status VARCHAR(20) NOT NULL DEFAULT 'open', root_cause TEXT, resolution TEXT, failed_attempts JSONB NOT NULL DEFAULT '[]', outcome VARCHAR(30), engineer_notes TEXT NOT NULL DEFAULT '', created_by INTEGER REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS timeline_events (id SERIAL PRIMARY KEY, incident_id INTEGER NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, event_type VARCHAR(50) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS chat_messages (id SERIAL PRIMARY KEY, user_id INTEGER REFERENCES users(id), role VARCHAR(20) NOT NULL, content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_incidents_created_at ON incidents(created_at DESC);
